package com.ruoyi.medical.persistence;
import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import org.springframework.beans.factory.ObjectProvider;import com.ruoyi.medical.persistence.mapper.*;
@Configuration(proxyBeanMethods=false)
@ConditionalOnExpression("${medical.formal-agent-acceptance.enabled:false} and ${medical.expert-qualification.enabled:false}")
public class FormalAgentAcceptanceConfiguration {
 @Bean FormalEvaluationScoreBindingSchema formalEvaluationScoreBindingSchema(FormalAgentPublicationSchema s)throws Exception{return new FormalEvaluationScoreBindingSchema(s);}
 @Bean FormalAgentAcceptanceEvidence formalAgentAcceptanceEvidence(EnterpriseAccess a,EvaluationService e,EvaluationSchema es,FormalAgentPublicationSchema s,PermissionSchema j,FormalAgentCandidateAuthority c,EvaluationAcceptancePolicyService p,ExpertQualificationAuthority q,ExpertQualificationStore qs,ObjectProvider<FormalEvaluationExecutionEvidence> executions,EvaluationAcceptanceEvidenceSchema evidenceSchema,EvaluationRuleAuthority rules,EvaluationReferences refs,AgentPublicationDependencies deps){return new FormalAgentAcceptanceEvidence(a,e,es,s,j,c,p,q,qs,executions,new EvaluationAcceptanceStatisticsEngine(j,es,evidenceSchema),rules,refs,deps);}
 @Bean FormalAgentAcceptanceService formalAgentAcceptanceService(EnterpriseAccess a,FormalAgentPublicationSchema s,PermissionSchema j,FormalAgentAcceptanceEvidence e,FormalAgentCandidateStore c,FormalAgentAcceptanceStore store,AgentPublicationJournal journal,AgentPublicationMapper versions,FormalAgentAcceptanceMapper mapper,ResourceReadAuthority resources,EvaluationService evaluations){return new FormalAgentAcceptanceService(a,s,j,e,c,store,journal,versions,mapper,resources,evaluations);}
 @Bean FormalEvaluationScoreBindingService formalEvaluationScoreBindingService(EnterpriseAccess a,FormalAgentAcceptanceEvidence e,FormalEvaluationScoreBindingSchema s,FormalAgentPublicationSchema j,ExpertQualificationService experts,ExpertQualificationStore store,ExpertQualificationAuthority authority){return new FormalEvaluationScoreBindingService(a,e,s,j,experts,store,authority);}
}
